import { applicationPlugins } from "@kasperrt/smolter/preact/vite";

export default {
  plugins: applicationPlugins({
    routeDiscovery: {
      protect: (route) => route.path.startsWith("/admin"),
      manifestFile: "dist/server/route-discovery.json",
    },
  }),
};

import { readFile } from "node:fs/promises";
import { createRequestHandler } from "@kasperrt/smolter/utils/http";

const manifest = JSON.parse(
  await readFile("dist/server/route-discovery.json", "utf8"),
);

app.use(
  createRequestHandler({
    build,
    entry,
    routeDiscovery: {
      manifest,
      authorize: async (request, route) =>
        route.path.startsWith("/admin") && (await isAdmin(request)),
    },
  }),
);

import routes, { discover } from "virtual:smolter/routes";
import { mountApplication } from "@kasperrt/smolter/preact/client";

const router = await mountApplication(routes, root, { discover });

export async function logout() {
  await fetch("/logout", { method: "POST" });
  router.resetDiscovery?.();
  await router.navigate("/");
}
